ALTER TABLE version_fixture ADD COLUMN nomination_id uuid;
CALL pg_temp.version_write('create snake room',$cmd$UPDATE version_fixture SET draft_id=(public.create_mock_draft_room_atomic(league_id,member_ids[1],user_ids[1],'Version snake','snake',NULL,'user_nominated',3,60,NULL,'auto_pick')).id$cmd$);
CALL pg_temp.version_write('join snake room',$cmd$SELECT public.join_mock_draft_room_atomic(draft_id,member_ids[2],user_ids[2]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('leave snake room',$cmd$SELECT public.leave_mock_draft_room_atomic(draft_id,member_ids[2],user_ids[2]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('rejoin snake room',$cmd$SELECT public.join_mock_draft_room_atomic(draft_id,member_ids[2],user_ids[2]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('start snake room',$cmd$SELECT public.start_mock_draft_room_atomic(draft_id,member_ids[1],user_ids[1]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('make snake pick',$cmd$SELECT public.make_snake_pick_atomic(f.draft_id,(SELECT member_id FROM public.snake_draft_picks WHERE draft_id=f.draft_id AND player_id IS NULL ORDER BY overall_pick LIMIT 1),f.players[3]) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('wait commissioner pick',$cmd$UPDATE public.drafts SET status='paused',pause_reason='timer_expired_commissioner_pick',timer_expiry_behavior='commissioner_pick' WHERE id=(SELECT draft_id FROM version_fixture)$cmd$);
CALL pg_temp.version_write('commissioner snake pick',$cmd$SELECT public.commissioner_snake_pick_atomic(f.draft_id,(SELECT member_id FROM public.snake_draft_picks WHERE draft_id=f.draft_id AND player_id IS NULL ORDER BY overall_pick LIMIT 1),f.players[4],f.user_ids[1]) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('restore auto timeout',$cmd$UPDATE public.drafts SET timer_expiry_behavior='auto_pick' WHERE id=(SELECT draft_id FROM version_fixture)$cmd$);
CALL pg_temp.version_write('automatic snake pick',$cmd$SELECT public.auto_pick_snake_pick_atomic(f.draft_id,(SELECT member_id FROM public.snake_draft_picks WHERE draft_id=f.draft_id AND player_id IS NULL ORDER BY overall_pick LIMIT 1)) FROM version_fixture f$cmd$);
CALL pg_temp.version_write('expire snake timer',$cmd$UPDATE public.snake_draft_picks SET timer_expires_at=now()-interval '1 minute' WHERE id=(SELECT pick.id FROM public.snake_draft_picks pick JOIN version_fixture f ON f.draft_id=pick.draft_id WHERE pick.player_id IS NULL AND pick.skipped_at IS NULL ORDER BY pick.overall_pick LIMIT 1)$cmd$);
CALL pg_temp.version_write('expired snake worker',$cmd$SELECT public.process_expired_snake_pick_atomic(draft_id) FROM version_fixture$cmd$);
CALL pg_temp.version_write('expire batch timer',$cmd$UPDATE public.snake_draft_picks SET timer_expires_at=now()-interval '1 minute' WHERE id=(SELECT pick.id FROM public.snake_draft_picks pick JOIN version_fixture f ON f.draft_id=pick.draft_id WHERE pick.player_id IS NULL AND pick.skipped_at IS NULL ORDER BY pick.overall_pick LIMIT 1)$cmd$);
CALL pg_temp.version_write('expired snake batch worker',$cmd$SELECT public.process_expired_snake_picks_atomic(1)$cmd$);
CALL pg_temp.version_write('reset snake draft',$cmd$SELECT public.reset_draft_atomic(draft_id) FROM version_fixture$cmd$);
CALL pg_temp.version_write('rookie pick inventory',$cmd$INSERT INTO public.draft_picks(league_id,season_year,round,original_owner_id,current_owner_id) SELECT f.league_id,9562,round,member,member FROM version_fixture f CROSS JOIN unnest(f.member_ids[1:2]) member CROSS JOIN generate_series(1,2) round$cmd$);
