CALL pg_temp.version_write('create auction room',$cmd$UPDATE version_fixture SET draft_id=(public.create_mock_draft_room_atomic(league_id,member_ids[1],user_ids[1],'Version auction','auction',NULL,'user_nominated',3,30,200,'auto_pick')).id$cmd$);
CALL pg_temp.version_write('join auction room',$cmd$SELECT public.join_mock_draft_room_atomic(draft_id,member_ids[2],user_ids[2]) FROM version_fixture$cmd$);
