CALL pg_temp.version_write('auction bid',$cmd$SELECT public.place_auction_bid_atomic(draft_id,member_ids[2],nomination_id,1,user_ids[2]) FROM version_fixture$cmd$);
CALL pg_temp.version_write('expire nomination',$cmd$UPDATE public.nominations SET countdown_expires_at=now()-interval '1 minute' WHERE id=(SELECT nomination_id FROM version_fixture)$cmd$);
